    ny_core = max(1, int(round(h_core_y / dy)))
    ix0 = (nx - nx_core) // 2
    iy0 = (ny - ny_core) // 2
    eps[ix0:ix0 + nx_core, iy0:iy0 + ny_core] = 3.476 ** 2
    return eps


