class TestR366MultiLevelAmr:
    """R366 多级 AMR FDTD 测试。"""

    def test_amr_solver_runs_and_shapes(self) -> None:
        """多级 AMR 求解器端到端运行 + 输出形状正确（Deng 2022 §III）。

        配置 L0(200) + L1(80-120, factor=4) + L2(90-110, factor=4)，
        运行 50 主步，验证主网格历史形状 (51, 200) 与加密层字段存在。
        """
        cfg = MultiLevelAmrConfig(
            n_main=200,
            dx_main=1e-7,
            dt_main=2e-16,
            n_steps=50,
            eps_r=1.0,
            source_idx=10,
            source_amplitude=1.0,
            source_freq=1e14,
            levels=(
                AmrLevel(level=1, i0=80, i1=120, factor=4),
                AmrLevel(level=2, i0=90, i1=110, factor=4),
            ),
        )
        solver = MultiLevelAmrFdtdSolver(cfg)
        result = solver.solve()
        assert result.e_main_history.shape == (51, 200)
        assert result.time.shape == (51,)
        assert 1 in result.level_fields  # L1 字段
        assert 2 in result.level_fields  # L2 字段
        # L2 子网格点数 = (110-90)*4 + 1 = 81
        assert result.level_fields[2].shape[0] == 81
        # 场有限（数值稳定）
        assert np.all(np.isfinite(result.e_main_history))

    def test_gradient_error_indicator_normalized(self) -> None:
        """Berger-Oliger 误差指示子归一化到 [0,1]，二次函数最大值=1。"""
        # 二次场 E(x) = x^2，二阶差分 = 2（常数），归一化后全部 = 1
        x = np.linspace(-1.0, 1.0, 21)
        field_quad = x ** 2
        eta = gradient_error_indicator(field_quad, dx=0.1)
        assert eta.shape == field_quad.shape
        assert eta.min() >= 0.0
        assert eta.max() <= 1.0 + 1e-12
        # 内部点（非边界）二阶差分恒为 2/dx²，归一化后 = 1
        assert abs(eta[10] - 1.0) < 1e-9
        # 线性场二阶差分 = 0，全场无需加密
        field_lin = x.copy()
        eta_lin = gradient_error_indicator(field_lin, dx=0.1)
        assert np.max(eta_lin) == 0.0

    def test_select_amr_regions_min_cells_expansion(self) -> None:
        """区间选择 + min_cells 扩展逻辑（Berger & Oliger 1984 §3）。"""
        # 指示子：仅 i=50 一点超阈值
        indicator = np.zeros(100)
        indicator[50] = 1.0
        regions = select_amr_regions(indicator, threshold=0.5, min_cells=6)
        assert len(regions) == 1
        i0, i1 = regions[0]
        # 原长度 1 < min_cells=6，需扩展到至少 6 个点
        assert i1 - i0 + 1 >= 6
        # 扩展后区间仍包含原触发点 50
        assert i0 <= 50 <= i1
        # 边界保护：不越界 [0, 99]
        assert 0 <= i0 < i1 <= 99

    def test_flops_ratio_amr_saves_vs_full_fine(self) -> None:
        """多级 AMR FLOPS 比 < 1（相对全细网格节省，Berger & Colella 1989 §3）。"""
        cfg = MultiLevelAmrConfig(
            n_main=200,
            dx_main=1e-7,
            dt_main=2e-16,
            n_steps=10,
            levels=(
                AmrLevel(level=1, i0=80, i1=120, factor=4),
                AmrLevel(level=2, i0=90, i1=110, factor=4),
            ),
        )
        solver = MultiLevelAmrFdtdSolver(cfg)
        ratio = solver._flops_ratio()
        # 多级 AMR 应当比全细网格（factor=16）节省 FLOPS → ratio > 1
        assert ratio > 1.0
        # 理论估算：fine_cost = 200*16 = 3200，
        # amr_cost = 200 + 40*(4-1) + 20*(4-1)*4 = 200+120+240 = 560
        # ratio = 3200/560 ≈ 5.71
        assert 1.0 < ratio < 20.0


