# R367 CPML 卷积完美匹配层（Roden & Gedney 2000）
# ============================================================================


class TestR367Cpml:
    """R367 CPML 吸收边界测试。"""

    def test_build_cpml_shape_and_layers(self) -> None:
        """build_cpml 系数形状与层数正确（Roden & Gedney 2000 §II）。"""
        nx, ny = 30, 30
        cx, cy, buffers = build_cpml(
            shape=(nx, ny),
            dx=1e-7,
            dy=1e-7,
            dt=1e-16,
            pml=CpmlConfig(layers=5, order=3),
            eps_r_bg=1.0,
        )
        assert cx.sigma.shape == (nx,)
        assert cy.sigma.shape == (ny,)
        assert cx.layers == 5
        # ψ 缓冲区形状 (nx, ny)
        assert buffers.psi_e_xz.shape == (nx, ny)
        assert buffers.psi_h_yx.shape == (nx, ny)

    def test_cpml_internal_region_zero(self) -> None:
        """内部（非 PML）区域 σ=0, a=0, b=1（CPML 不影响内部场）。"""
        n = 30
        cx, _, _ = build_cpml(
            shape=(n, n),
            dx=1e-7,
            dy=1e-7,
            dt=1e-16,
            pml=CpmlConfig(layers=5),
            eps_r_bg=1.0,
        )
        # 内部点 i ∈ [5, 25)
        internal = slice(5, 25)
        assert np.all(cx.sigma[internal] == 0.0)
        assert np.all(cx.a[internal] == 0.0)
        assert np.allclose(cx.b[internal], 1.0)
        assert np.all(cx.kappa[internal] == 1.0)

    def test_cpml_boundary_region_nonzero(self) -> None:
        """PML 边界区域 σ>0, a<0, b<1（Gedney 1996 σ 多项式渐变）。"""
        n = 30
        cx, _, _ = build_cpml(
            shape=(n, n),
            dx=1e-7,
            dy=1e-7,
            dt=1e-16,
            pml=CpmlConfig(layers=5, order=3),
            eps_r_bg=1.0,
        )
        # 左外边界 i=0：σ 最大（距外边界深度=5*dx=L_pml，归一化深度=1）
        assert cx.sigma[0] > 0.0
        # σ 渐变：左边界层 i=0..4，σ[i] 应递减（外边界最大）
        # 注：左 PML depth = (5 - idx)*dx，idx=0 → depth=5*dx（外边界），
        # idx=4 → depth=1*dx（内边界），故 sigma[0] > sigma[4]
        assert cx.sigma[0] > cx.sigma[4]
        # a 在 PML 区为负（b-1 < 0，因 b = exp(-(σ/κ+α)·dt/ε₀) < 1）
        assert cx.a[0] < 0.0
        assert cx.b[0] < 1.0

    def test_reflection_db_formula_and_validation(self) -> None:
        """reflection_db 公式验证（A09 §13.2 验收点 ≤−60dB）。

        R_dB = 20·log10(reflected/incident)
        - 完美吸收（reflected=0）→ -inf
        - 1% 反射 → -40 dB
        - 非法输入 raise（R03）
        """
        # 1% 反射 → -40 dB
        assert abs(reflection_db(1.0, 0.01) - (-40.0)) < 1e-9
        # 0.1% 反射 → -60 dB（CPML 设计目标）
        assert abs(reflection_db(1.0, 0.001) - (-60.0)) < 1e-9
        # 完美吸收 → -inf
        assert reflection_db(1.0, 0.0) == -np.inf
        # 非法输入 raise（规则 14：禁止 fall-back）
        with pytest.raises(ValueError):
            reflection_db(0.0, 0.1)  # incident ≤ 0
        with pytest.raises(ValueError):
            reflection_db(1.0, -0.1)  # reflected < 0


