# R366 FDTD 多级自适应网格加密（AMR，Berger-Oliger 级联细化）
# ============================================================================


class TestR366MultiLevelAmr:
    """R366 多级 AMR FDTD 测试。"""

    def test_amr_solver_runs_and_shapes(self) -> None:
        """多级 AMR 求解器端到端运行 + 输出形状正确（Deng 2022 §III）。

        配置 L0(200) + L1(80-120, factor=4) + L2(90-110, factor=4)，
        运行 50 主步，验证主网格历史形状 (51, 200) 与加密层字段存在。
        """
        cfg = MultiLevelAmrConfig(
            n_main=200,
            dx_main=1e-7,
            dt_main=2e-16,
            n_steps=50,
            eps_r=1.0,
            source_idx=10,
            source_amplitude=1.0,
            source_freq=1e14,
            levels=(
                AmrLevel(level=1, i0=80, i1=120, factor=4),
                AmrLevel(level=2, i0=90, i1=110, factor=4),
            ),
        )
        solver = MultiLevelAmrFdtdSolver(cfg)
        result = solver.solve()
        assert result.e_main_history.shape == (51, 200)
        assert result.time.shape == (51,)
        assert 1 in result.level_fields  # L1 字段
        assert 2 in result.level_fields  # L2 字段
        # L2 子网格点数 = (110-90)*4 + 1 = 81
        assert result.level_fields[2].shape[0] == 81
        # 场有限（数值稳定）
        assert np.all(np.isfinite(result.e_main_history))

    def test_gradient_error_indicator_normalized(self) -> None:
        """Berger-Oliger 误差指示子归一化到 [0,1]，二次函数最大值=1。"""
        # 二次场 E(x) = x^2，二阶差分 = 2（常数），归一化后全部 = 1
        x = np.linspace(-1.0, 1.0, 21)
        field_quad = x ** 2
        eta = gradient_error_indicator(field_quad, dx=0.1)
        assert eta.shape == field_quad.shape
        assert eta.min() >= 0.0
        assert eta.max() <= 1.0 + 1e-12
        # 内部点（非边界）二阶差分恒为 2/dx²，归一化后 = 1
        assert abs(eta[10] - 1.0) < 1e-9
        # 线性场二阶差分 = 0，全场无需加密
        field_lin = x.copy()
        eta_lin = gradient_error_indicator(field_lin, dx=0.1)
        assert np.max(eta_lin) == 0.0

    def test_select_amr_regions_min_cells_expansion(self) -> None:
        """区间选择 + min_cells 扩展逻辑（Berger & Oliger 1984 §3）。"""
        # 指示子：仅 i=50 一点超阈值
        indicator = np.zeros(100)
        indicator[50] = 1.0
        regions = select_amr_regions(indicator, threshold=0.5, min_cells=6)
        assert len(regions) == 1
        i0, i1 = regions[0]
        # 原长度 1 < min_cells=6，需扩展到至少 6 个点
        assert i1 - i0 + 1 >= 6
        # 扩展后区间仍包含原触发点 50
        assert i0 <= 50 <= i1
        # 边界保护：不越界 [0, 99]
        assert 0 <= i0 < i1 <= 99

    def test_flops_ratio_amr_saves_vs_full_fine(self) -> None:
        """多级 AMR FLOPS 比 < 1（相对全细网格节省，Berger & Colella 1989 §3）。"""
        cfg = MultiLevelAmrConfig(
            n_main=200,
            dx_main=1e-7,
            dt_main=2e-16,
            n_steps=10,
            levels=(
                AmrLevel(level=1, i0=80, i1=120, factor=4),
                AmrLevel(level=2, i0=90, i1=110, factor=4),
            ),
        )
        solver = MultiLevelAmrFdtdSolver(cfg)
        ratio = solver._flops_ratio()
        # 多级 AMR 应当比全细网格（factor=16）节省 FLOPS → ratio > 1
        assert ratio > 1.0
        # 理论估算：fine_cost = 200*16 = 3200，
        # amr_cost = 200 + 40*(4-1) + 20*(4-1)*4 = 200+120+240 = 560
        # ratio = 3200/560 ≈ 5.71
        assert 1.0 < ratio < 20.0


# ============================================================================
# R367 CPML 卷积完美匹配层（Roden & Gedney 2000）
# ============================================================================


class TestR367Cpml:
    """R367 CPML 吸收边界测试。"""

    def test_build_cpml_shape_and_layers(self) -> None:
        """build_cpml 系数形状与层数正确（Roden & Gedney 2000 §II）。"""
        nx, ny = 30, 30
        cx, cy, buffers = build_cpml(
            shape=(nx, ny),
            dx=1e-7,
            dy=1e-7,
            dt=1e-16,
            pml=CpmlConfig(layers=5, order=3),
            eps_r_bg=1.0,
        )
        assert cx.sigma.shape == (nx,)
        assert cy.sigma.shape == (ny,)
        assert cx.layers == 5
        # ψ 缓冲区形状 (nx, ny)
        assert buffers.psi_e_xz.shape == (nx, ny)
        assert buffers.psi_h_yx.shape == (nx, ny)

    def test_cpml_internal_region_zero(self) -> None:
        """内部（非 PML）区域 σ=0, a=0, b=1（CPML 不影响内部场）。"""
        n = 30
        cx, _, _ = build_cpml(
            shape=(n, n),
            dx=1e-7,
            dy=1e-7,
            dt=1e-16,
            pml=CpmlConfig(layers=5),
            eps_r_bg=1.0,
        )
        # 内部点 i ∈ [5, 25)
        internal = slice(5, 25)
        assert np.all(cx.sigma[internal] == 0.0)
        assert np.all(cx.a[internal] == 0.0)
        assert np.allclose(cx.b[internal], 1.0)
        assert np.all(cx.kappa[internal] == 1.0)

    def test_cpml_boundary_region_nonzero(self) -> None:
        """PML 边界区域 σ>0, a<0, b<1（Gedney 1996 σ 多项式渐变）。"""
        n = 30
        cx, _, _ = build_cpml(
            shape=(n, n),
            dx=1e-7,
            dy=1e-7,
            dt=1e-16,
            pml=CpmlConfig(layers=5, order=3),
            eps_r_bg=1.0,
        )
        # 左外边界 i=0：σ 最大（距外边界深度=5*dx=L_pml，归一化深度=1）
        assert cx.sigma[0] > 0.0
        # σ 渐变：左边界层 i=0..4，σ[i] 应递减（外边界最大）
        # 注：左 PML depth = (5 - idx)*dx，idx=0 → depth=5*dx（外边界），
        # idx=4 → depth=1*dx（内边界），故 sigma[0] > sigma[4]
        assert cx.sigma[0] > cx.sigma[4]
        # a 在 PML 区为负（b-1 < 0，因 b = exp(-(σ/κ+α)·dt/ε₀) < 1）
        assert cx.a[0] < 0.0
        assert cx.b[0] < 1.0

    def test_reflection_db_formula_and_validation(self) -> None:
        """reflection_db 公式验证（A09 §13.2 验收点 ≤−60dB）。

        R_dB = 20·log10(reflected/incident)
        - 完美吸收（reflected=0）→ -inf
        - 1% 反射 → -40 dB
        - 非法输入 raise（R03）
        """
        # 1% 反射 → -40 dB
        assert abs(reflection_db(1.0, 0.01) - (-40.0)) < 1e-9
        # 0.1% 反射 → -60 dB（CPML 设计目标）
        assert abs(reflection_db(1.0, 0.001) - (-60.0)) < 1e-9
        # 完美吸收 → -inf
        assert reflection_db(1.0, 0.0) == -np.inf
        # 非法输入 raise（规则 14：禁止 fall-back）
        with pytest.raises(ValueError):
            reflection_db(0.0, 0.1)  # incident ≤ 0
        with pytest.raises(ValueError):
            reflection_db(1.0, -0.1)  # reflected < 0


# ============================================================================
# R368 FDE 模式求解加速（shift-invert Arnoldi，ARPACK）
# ============================================================================


def _make_soi_strip_eps(nx: int = 50, ny: int = 50) -> np.ndarray:
    """构造 SOI strip 波导 2D 介电常数分布（测试用）。

    Si 核心 (n=3.476) 220nm × 500nm，SiO₂ 包层 (n=1.444)。
    Soref 1993 IEEE JQE 27(3) 113-118 参数。
    """
    eps = np.full((nx, ny), 1.444 ** 2, dtype=np.float64)  # SiO₂ 包层
    # Si 核心：中心 220nm 高 × 500nm 宽
    w_core_x = 500e-9  # 宽度 500nm（x 方向）
    h_core_y = 220e-9  # 高度 220nm（y 方向）
    window_x = 3e-6  # 总窗口 3μm
    window_y = 3e-6
    dx = window_x / nx
    dy = window_y / ny
    nx_core = max(1, int(round(w_core_x / dx)))
    ny_core = max(1, int(round(h_core_y / dy)))
    ix0 = (nx - nx_core) // 2
    iy0 = (ny - ny_core) // 2
    eps[ix0:ix0 + nx_core, iy0:iy0 + ny_core] = 3.476 ** 2
    return eps


class TestR368FdeShiftInvert:
    """R368 FDE shift-invert Arnoldi 加速测试。"""

    def test_fde_soi_strip_fundamental_neff(self) -> None:
        """SOI strip TE 基模 n_eff ∈ (2.0, 3.0)（Tidy3D 实测 2.51-2.67）。

        shift-invert 目标 σ=(k₀·n_eff_shift)² 加速命中导模，避免体模。
        """
        eps_r = _make_soi_strip_eps(40, 40)
        cfg = FdeSolverConfig(
            wavelength=1.55e-6,
            num_modes=2,
            polarization=Polarization.TE,
        )
        solver = FdeSolver(cfg)
        modes = solver.solve(eps_r, window_size=(3e-6, 3e-6))
        assert len(modes) >= 1
        # 基模 n_eff 应在导模范围 (n_clad=1.444, n_core=3.476)
        n_eff0 = float(np.real(modes[0].n_eff))
        assert 1.5 < n_eff0 < 3.4, f"基模 n_eff={n_eff0} 超出导模范围"
        # SOI strip TE0 权威实测 2.51-2.67（Tidy3D n_Si=3.4 / 本项目 n_Si=3.476）
        assert 2.0 < n_eff0 < 3.0

    def test_fde_invalid_input_raises(self) -> None:
        """非法输入必须 raise（R03 禁止 fall-back）。"""
        # 波长非正
        with pytest.raises(ValueError):
            FdeSolverConfig(wavelength=-1.0e-6, num_modes=1)
        # 模式数 < 1
        with pytest.raises(ValueError):
            FdeSolverConfig(wavelength=1.55e-6, num_modes=0)
        # 偏振非法
        with pytest.raises(ValueError):
            FdeSolverConfig(wavelength=1.55e-6, polarization="TEM")
        # 网格过小
        cfg = FdeSolverConfig(wavelength=1.55e-6, num_modes=1)
        solver = FdeSolver(cfg)
        with pytest.raises(ValueError):
            solver.solve(np.ones((3, 3)), window_size=(1e-6, 1e-6))

    def test_fde_te_polarization_fraction(self) -> None:
        """TE 半矢量求解基模 te_fraction ≈ 1.0（Xu & Huang 1994）。"""
        eps_r = _make_soi_strip_eps(40, 40)
        cfg = FdeSolverConfig(
            wavelength=1.55e-6,
            num_modes=1,
            polarization=Polarization.TE,
        )
        modes = FdeSolver(cfg).solve(eps_r, window_size=(3e-6, 3e-6))
        assert len(modes) >= 1
        # TE 半矢量（E_y 主导）→ te_fraction ≈ 1.0
        assert modes[0].te_fraction > 0.95, (
            f"TE 模 te_fraction={modes[0].te_fraction} 应 > 0.95"
        )
        # 1W 功率归一化标志
        assert modes[0].normalized is True


# ============================================================================
# R369 EME 自适应模式数（收敛性驱动 + Richardson 外推）
# ============================================================================


def _convergent_s_matrix_fn(M: int) -> np.ndarray:
    """构造随 M 单调收敛的全局 S 矩阵（测试用，模拟 EME 模式收敛）。

    S = I_{2M} + diag(1/M, 0, ..., 0)
    M 增大时 S[0,0] → 1.0（收敛），相邻 M 差异 ~ 1/M²（Richardson 可估阶）。
    """
    s = np.eye(2 * M, dtype=np.float64)
    s[0, 0] = 1.0 + 1.0 / M
    return s


class TestR369EmeAdaptiveModeSelector:
    """R369 EME 自适应模式数选择测试。"""

    def test_adaptive_select_converges_to_min_m(self) -> None:
        """收敛性驱动选择最小 M 使相对误差 < 阈值（Gallagher 2003 §3）。"""
        selector = EmeAdaptiveModeSelector(solve_fn=_convergent_s_matrix_fn)
        # threshold=0.05：M=8 时 eps≈0.0427 < 0.05 → selected=8
        result = selector.select(
            candidate_Ms=[2, 4, 8, 16], threshold=0.05
        )
        assert result.selected_count == 8
        # 收敛历史记录每步误差
        assert len(result.convergence_history) >= 1
        # 节省倍数 = max_M² / selected_M² = 16²/8² = 4
        assert abs(result.speedup_factor - 4.0) < 1e-9
        # 相对误差 < 阈值
        assert result.relative_error < 0.05

    def test_no_convergence_raises(self) -> None:
        """所有候选 M 均未收敛 → raise（R03 禁止 fall-back）。"""
        selector = EmeAdaptiveModeSelector(solve_fn=_convergent_s_matrix_fn)
        # threshold=0.001：所有 eps > 0.001 → 不收敛
        with pytest.raises(ValueError, match="未收敛"):
            selector.select(candidate_Ms=[2, 4, 8], threshold=0.001)

    def test_invalid_input_raises(self) -> None:
        """非法阈值/候选列表 → raise（R03）。"""
        selector = EmeAdaptiveModeSelector(solve_fn=_convergent_s_matrix_fn)
        # 候选列表仅 1 项
        with pytest.raises(ValueError, match="至少 2 项"):
            selector.select(candidate_Ms=[4], threshold=0.05)
        # 候选列表非升序
        with pytest.raises(ValueError, match="严格升序"):
            selector.select(candidate_Ms=[8, 4, 2], threshold=0.05)
        # 阈值越界
        with pytest.raises(ValueError, match="threshold"):
            selector.select(candidate_Ms=[2, 4], threshold=1.5)
        with pytest.raises(ValueError, match="threshold"):
            selector.select(candidate_Ms=[2, 4], threshold=0.0)
        # norm 非法
        with pytest.raises(ValueError):
            EmeAdaptiveModeSelector(
                solve_fn=_convergent_s_matrix_fn, norm="l2"
            )


# ============================================================================
# R370 BPM 大步长传播（Padé(1,1)/(2,2) 广义传播算子）
# ============================================================================


class TestR370BpmPadeLargeStep:
    """R370 BPM Padé 大步长传播测试。"""

    def test_pade_11_power_conservation_uniform_waveguide(self) -> None:
        """Padé(1,1) 在均匀无损波导中功率近似守恒（CN 等价，A-稳定）。

        均匀波导 n=n_ref → 无衍射、无反射，ψ 仅相位累积，|ψ|² 守恒。
        Hadley 1994 Padé(1,1) ≡ CN θ=0.5，二阶精度 O(Δz²)。
        """
        nx = 64
        n_profile = np.full(nx, 2.0)  # 均匀折射率
        prop = BpmPadeLargeStep(
            n_profile=n_profile,
            wavelength=1.55e-6,
            dx=50e-9,
            n_ref=2.0,
        )
        # 高斯初始场
        x = (np.arange(nx) - nx / 2) * 50e-9
        psi_0 = np.exp(-(x ** 2) / (0.5e-6) ** 2).astype(np.complex128)
        result = prop.propagate(
            psi_0, dz=0.5e-6, n_steps=20, pade_order=(1, 1)
        )
        assert result.field_history.shape == (21, nx)
        # 功率守恒：均匀波导无损 → |P_final - P_0| / P_0 < 1e-6
        p0 = result.power_history[0]
        p_final = result.power_history[-1]
        assert abs(p_final - p0) / p0 < 1e-6, (
            f"Padé(1,1) 功率不守恒: P0={p0}, P_final={p_final}"
        )
        assert result.pade_order == (1, 1)

    def test_pade_22_stable_at_large_step(self) -> None:
        """Padé(2,2) 大步长（3x CN）下数值稳定（Hadley 1994 四阶 A-稳定）。"""
        nx = 64
        n_profile = np.full(nx, 2.0)
        # 加一个小波导凹陷诱导衍射（验证 Padé(2,2) 在非均匀下稳定）
        n_profile[28:36] = 2.05
        prop = BpmPadeLargeStep(
            n_profile=n_profile,
            wavelength=1.55e-6,
            dx=50e-9,
            n_ref=2.0,
        )
        x = (np.arange(nx) - nx / 2) * 50e-9
        psi_0 = np.exp(-(x ** 2) / (0.5e-6) ** 2).astype(np.complex128)
        # Padé(2,2) 允许 3-5x 大步长（Hadley 1994）
        result = prop.propagate(
            psi_0, dz=1.5e-6, n_steps=15, pade_order=(2, 2)
        )
        assert result.field_history.shape == (16, nx)
        # 数值稳定：场有限
        assert np.all(np.isfinite(result.field_history))
        # 功率不应爆炸（A-稳定保证有界）
        p0 = result.power_history[0]
        p_max = float(np.max(result.power_history))
        assert p_max < 10.0 * p0, f"Padé(2,2) 功率爆炸: P_max={p_max}, P0={p0}"

    def test_pade_invalid_order_raises(self) -> None:
        """不支持的 Padé 阶数 → raise（R03）。"""
        n_profile = np.full(32, 2.0)
        prop = BpmPadeLargeStep(
            n_profile=n_profile,
            wavelength=1.55e-6,
            dx=50e-9,
            n_ref=2.0,
        )
        psi_0 = np.ones(32, dtype=np.complex128)
        with pytest.raises(ValueError, match="pade_order"):
            prop.propagate(psi_0, dz=1e-6, n_steps=5, pade_order=(3, 3))
        with pytest.raises(ValueError, match="pade_order"):
            prop.propagate(psi_0, dz=1e-6, n_steps=5, pade_order=(1, 2))

    def test_pade_invalid_dz_and_steps_raises(self) -> None:
        """非法 dz/n_steps → raise（R03）。"""
        n_profile = np.full(32, 2.0)
        prop = BpmPadeLargeStep(
            n_profile=n_profile,
            wavelength=1.55e-6,
            dx=50e-9,
            n_ref=2.0,
        )
        psi_0 = np.ones(32, dtype=np.complex128)
        with pytest.raises(ValueError, match="dz"):
            prop.propagate(psi_0, dz=-1e-6, n_steps=5, pade_order=(1, 1))
        with pytest.raises(ValueError, match="n_steps"):
            prop.propagate(psi_0, dz=1e-6, n_steps=0, pade_order=(1, 1))


# ============================================================================
# R371 JAX 向量化 FDTD（jax.lax.scan 时间步进，Mahlau 2024）
# ============================================================================


class TestR371JaxVectorizedFdtd:
    """R371 JAX 向量化 FDTD 测试（CPU 后端，R04 不参与 GPU）。"""

    def test_run_returns_correct_shapes(self) -> None:
        """jax.lax.scan 时间步进返回正确形状（Mahlau 2024 arXiv:2412.12360）。"""
        nx, ny, nz = 10, 10, 10
        grid = YeeGrid3D(
            nx=nx, ny=ny, nz=nz,
            dx=5e-8, dy=5e-8, dz=5e-8,
        )
        eps_r = jnp.ones((nx, ny, nz))  # 真空
        pml = GedneyPML(grid, n_layers=2)
        fdtd = DifferentiableFDTD(grid, pml=pml, dt=1e-17)
        result = fdtd.run(
            epsilon_r=eps_r,
            source_pos=(5, 5, 5),
            source_freq=2e14,
            n_steps=10,
            monitor_pos=(7, 5, 5),
        )
        # 返回 6 个场分量 + monitor_signal
        assert "Ex" in result and "Ey" in result and "Ez" in result
        assert "Hx" in result and "Hy" in result and "Hz" in result
        assert "monitor_signal" in result
        # 场形状 = (nx, ny, nz)
        assert result["Ex"].shape == (nx, ny, nz)
        # monitor_signal 长度 = n_steps
        assert result["monitor_signal"].shape == (10,)

    def test_source_propagates_to_monitor(self) -> None:
        """源注入后 monitor_signal 后段非零（Yee leapfrog 物理传播）。"""
        nx, ny, nz = 12, 12, 12
        grid = YeeGrid3D(
            nx=nx, ny=ny, nz=nz,
            dx=5e-8, dy=5e-8, dz=5e-8,
        )
        eps_r = jnp.ones((nx, ny, nz))
        pml = GedneyPML(grid, n_layers=2)
        fdtd = DifferentiableFDTD(grid, pml=pml, dt=1e-17)
        result = fdtd.run(
            epsilon_r=eps_r,
            source_pos=(3, 6, 6),
            source_freq=2e14,
            n_steps=30,
            monitor_pos=(9, 6, 6),
        )
        mon = np.asarray(result["monitor_signal"])
        # 后段（源已传播到 monitor）应有非零值
        assert np.any(np.abs(mon[15:]) > 0.0), (
            "monitor_signal 后段全零，源未传播"
        )

"""R366-R400 仿真器进阶功能综合测试（批次10-A，纯 NumPy/SciPy/JAX-CPU）。

路标 R366-R371 验证 6 个仿真器进阶功能的物理正确性与数值稳定性。源码已实现于：
- R366 FDTD 多级网格 AMR: src/polaris/sim/perf_optimization_fdtd.py
  （MultiLevelAmrFdtdSolver，Berger-Oliger 级联细化）
- R367 CPML 吸收边界: src/polaris/sim/fdtd/cpml.py
  （build_cpml，Roden & Gedney 2000 递归卷积 ADE）
- R368 FDE 模式求解加速: src/polaris/sim/fde/solver.py
  （FdeSolver，scipy.sparse.linalg.eigs shift-invert Arnoldi）
- R369 EME 自适应模式数: src/polaris/sim/perf_optimization_eme.py
  （EmeAdaptiveModeSelector，Richardson 外推收敛性驱动）
- R370 BPM 大步长传播: src/polaris/sim/perf_optimization_bpm.py
  （BpmPadeLargeStep，Padé(1,1)/(2,2) 广义传播算子）
- R371 JAX 向量化 FDTD: src/polaris/sim/fdtd_jax_backend.py
  （DifferentiableFDTD，jax.lax.scan 时间步进）

学术依据（R02 学术诚信，≥5 个文献 URL，均经 WebSearch 验证）:
1. Berger & Oliger 1984 J Comput Phys 53 484-512（AMR 级联框架）—
   https://doi.org/10.1016/0021-9991(84)90073-1
2. Roden & Gedney 2000 CPML Microwave Opt Technol Lett 27(5) 334-339 —
   https://doi.org/10.1002/1098-2760(20001205)27:5%3C334::AID-MOP14%3E3.0.CO;2-A
3. Lehoucq, Sorensen, Yang 1998 ARPACK Users Guide SIAM（shift-invert Arnoldi）—
   https://doi.org/10.1137/1.9780898719628
4. scipy ARPACK shift-invert 教程 —
   https://docs.scipy.org/doc//scipy-1.7.0/tutorial/arpack.html
5. Hadley 1994 Opt Lett 17 1426-1428（Padé wide-angle BPM）—
   https://doi.org/10.1364/OL.17.001426
6. Chiou & Chang 1997 Opt Lett 22 949（Padé BPM 高阶）—
   https://doi.org/10.1364/OL.22.000949
7. Mahlau et al. 2024 arXiv:2412.12360（JAX 可微分 FDTD lax.scan）—
   https://arxiv.org/abs/2412.12360
8. Yee 1966 IEEE Trans AP 14(3) 302-307（Yee 网格 leapfrog）—
   https://doi.org/10.1109/TAP.1966.1138693
9. Press et al. 2007 Numerical Recipes 3rd §18.5 Richardson 外推 —
   https://numerical.recipes/
10. Gedney 1996 IEEE Trans AP 44(12) 1630-1639（单轴 PML）—
    https://doi.org/10.1109/8.546242

规则依据（R03 禁止 fall-back / R04 不参与 GPU / R05 Bug 必修 / R11 V8 极简）
"""

from __future__ import annotations

import numpy as np
import pytest

# R371 JAX 测试：CPU 后端（R04 不参与 GPU 战略）
import jax
import jax.numpy as jnp

# R04 合规：JAX 默认 CPU backend（已验证 jax.default_backend()=='cpu'）
# 显式设置避免任何 GPU 探测
jax.config.update("jax_platform_name", "cpu")

